const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=localStorage.getItem('baan-lang')||'th';
const t=(th,en)=>lang==='th'?th:en;
const loc=o=>typeof o==='object'?(o?.[lang]||o?.th||o?.en||''):o||'';
const money=v=>'฿'+Number(v||0).toLocaleString(lang==='th'?'th-TH':'en-US',{maximumFractionDigits:2});
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',home:'<path d="m3 10 9-7 9 7v11H3V10Z"/><path d="M9 21v-8h6v8"/>',shirt:'<path d="m8 3-6 4 3 5 3-2v11h8V10l3 2 3-5-6-4c0 5-8 5-8 0Z"/>',sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/><path d="m20 2 1 3 3 1-3 1-1 3-1-3-3-1 3-1 1-3Z"/>',headphones:'<path d="M3 14v-3a9 9 0 0 1 18 0v3"/><rect x="3" y="12" width="4" height="9" rx="2"/><rect x="17" y="12" width="4" height="9" rx="2"/>',coffee:'<path d="M3 4h14v9a7 7 0 0 1-14 0V4Zm14 1h2a3 3 0 0 1 0 6h-2M2 22h17"/>',palette:'<path d="M12 3a9 9 0 1 0 0 18h2c3 0 3-4 0-4h-1a2 2 0 0 1 0-4h4c6 0 5-10-5-10Z"/><circle cx="7" cy="10" r=".5"/><circle cx="10" cy="7" r=".5"/><circle cx="15" cy="7" r=".5"/>',leaf:'<path d="M20 3c-1 7 3 15-7 17C3 22 1 12 8 8c3-2 7-1 12-5Z"/><path d="m4 22 12-12"/>',truck:'<path d="M2 4h12v13H2V4Zm12 5h5l3 5v3h-8"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="18" r="3"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',store:'<path d="M3 10v11h18V10M2 10l3-7h14l3 7M2 10c1 3 4 3 5 0 1 3 4 3 5 0 1 3 4 3 5 0 1 3 4 3 5 0M9 21v-7h6v7"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L20 5"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',box:'<path d="m12 2 10 5v10l-10 5-10-5V7l10-5Zm0 10L2 7m10 5L22 7m-10 5v10M7 4.5l10 5"/>',refresh:'<path d="M21 8V3l-3 3a9 9 0 1 0 3 10M21 3h-5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
let state={products:[],shops:[],settings:{categories:[]},user:null},orders=[],campaigns=[],myShops=[],category='',filter='all',sort='recommended',query='',shopCategory='',shuffle=Math.random(),selectedShop='',adminTab='appearance';
function saved(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
let cart=saved('baan-cart',[]),favorites=saved('baan-favorites',[]);
const saveCart=()=>localStorage.setItem('baan-cart',JSON.stringify(cart));
const cartCount=()=>cart.reduce((n,x)=>n+x.qty,0);
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json()}catch{throw Error(t('เซิร์ฟเวอร์ไม่พร้อมใช้งาน กรุณาลองใหม่','Server unavailable. Please try again.'))}if(!r.ok)throw Error(data.error||'Request failed');return data}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(content){$('#modal-root').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true"><button class="close" data-action="close" aria-label="${t('ปิด','Close')}">×</button>${content}</section></div>`;$('#modal-root').querySelector('input,button')?.focus()}
function closeModal(){$('#modal-root').innerHTML=''}
function empty(title,text,link='#/catalog',label=t('ค้นพบสินค้า','Discover products')){return `<div class="empty">${icon('bag')}<h2>${title}</h2><p>${text}</p><a class="btn" href="${link}">${label}${icon('arrow')}</a></div>`}
const btn=(label,action,id='',cls='')=>`<button class="btn ${cls}" data-action="${action}" data-id="${escape(id)}">${label}</button>`;
const shopName=id=>state.shops.find(s=>s.id===id)?.name||'';
const route=()=>location.hash.slice(1)||'/';
function brand(){const s=state.settings;return `<a class="brand" href="#/" aria-label="${escape(s.name)}">${s.logo?`<img src="${escape(s.logo)}" alt="${escape(s.name)}">`:`${icon('store')}<span>${escape(s.name)}<small>${escape(loc(s.tagline))}</small></span>`}</a>`}
function searchbox(mobile=false){return `<form class="search ${mobile?'mobile-search':''}" id="${mobile?'mobile-search':'search'}">${icon('search')}<input name="q" aria-label="${t('ค้นหาสินค้าหรือร้านค้า','Search products or shops')}" placeholder="${t('ค้นหาสิ่งดี ๆ สำหรับคุณ...','Find something good for your everyday...')}" value="${escape(query)}"><button aria-label="${t('ค้นหา','Search')}">${icon('arrow')}</button></form>`}
function header(){const r=route();return `<div class="topbar">${t('พื้นที่ของสิ่งดี ๆ จากร้านค้าอิสระ • เลือกอย่างใส่ใจ ใช้ได้ทุกวัน','Thoughtful finds from independent shops • Made for your everyday')}</div><header class="header"><div class="container head">${brand()}${searchbox()}<div class="head-tools"><div class="lang"><button data-action="lang" data-id="th" class="${lang==='th'?'active':''}">TH</button><span>/</span><button data-action="lang" data-id="en" class="${lang==='en'?'active':''}">EN</button></div><button class="tool" data-action="account" aria-label="${t('บัญชีของฉัน','My account')}">${icon('user')}<span>${escape(state.user?.name||t('เข้าสู่ระบบ','Sign in'))}</span></button><a href="#/wishlist" class="tool" aria-label="${t('รายการโปรด','Wishlist')}">${icon('heart')}</a><a href="#/cart" class="tool" aria-label="${t('ตะกร้า','Cart')}">${icon('bag')}<span>${t('ตะกร้า','Cart')}</span>${cartCount()?`<b class="count">${cartCount()}</b>`:''}</a></div></div><nav class="container nav"><a href="#/" class="${r==='/'?'selected':''}">${t('หน้าแรก','Discover')}</a><a href="#/catalog" class="${r==='/catalog'?'selected':''}">${icon('grid')}${t('สินค้าทั้งหมด','All products')}</a><a href="#/stores">${t('ร้านค้าทั้งหมด','Our shops')}</a><a href="#/catalog?deals">${t('ดีลพิเศษ','Special offers')} <span style="color:var(--accent)">✦</span></a><a href="#/orders">${t('ติดตามคำสั่งซื้อ','Track orders')}</a><a href="#/seller" class="right">${icon('store')}${t('เปิดร้านกับเรา','Become a seller')}${icon('arrow')}</a></nav></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-top"><div>${brand()}<p>${t('พื้นที่ที่เชื่อมคุณกับสินค้าที่มีเรื่องราว<br>และร้านค้าที่ใส่ใจในทุกวันของคุณ','Connecting you with thoughtful products<br>and the people who make them.')}</p></div><div class="footer-links"><div><strong>${t('ค้นพบ','Discover')}</strong><a href="#/catalog">${t('สินค้าทั้งหมด','All products')}</a><a href="#/stores">${t('ร้านค้าของเรา','Our shops')}</a><a href="#/wishlist">${t('รายการโปรด','Wishlist')}</a></div><div><strong>${t('ดูแลคุณ','Here to help')}</strong><a href="#/orders">${t('ติดตามคำสั่งซื้อ','Track an order')}</a><button data-action="help">${t('การชำระเงินและจัดส่ง','Payment & shipping')}</button><a href="#/account">${t('บัญชีสมาชิก','My account')}</a></div><div><strong>${t('เติบโตไปด้วยกัน','Grow with us')}</strong><a href="#/seller">${t('จัดการร้านค้า','Seller studio')}</a><a href="#/seller/sponsor">${t('พื้นที่แนะนำร้านค้า','Featured placements')}</a>${state.user?.role==='admin'?`<a href="#/admin">${t('จัดการเว็บไซต์','Site administration')}</a>`:''}</div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${escape(state.settings.name)}. Everyday, thoughtfully.</span><span>${t('คัดสรรด้วยใจ • ส่งตรงจากร้านค้า','Thoughtfully curated • Shipped by independent shops')} &nbsp; TH / EN</span></div></div></footer>`}
function card(p){const discount=Math.round((1-p.price/p.original)*100);return `<article class="product"><a href="#/product/${p.id}" class="product-image"><img src="${escape(p.images[0])}" alt="${escape(loc(p.name))}" loading="lazy">${discount>0?`<span class="badge">−${discount}%</span>`:''}${p.videos?.length?`<span class="video-badge">${icon('play')} ${t('มีวิดีโอ','Video')}</span>`:''}</a><button class="wish ${favorites.includes(p.id)?'on':''}" data-action="wish" data-id="${p.id}" aria-label="${t('บันทึกรายการโปรด','Save to wishlist')}">${icon('heart')}</button><div class="product-info"><a href="#/store/${p.shop}" class="shop-line">${icon('store')}${escape(shopName(p.shop))}${state.shops.find(s=>s.id===p.shop)?.verified?' <span>✓</span>':''}</a><a href="#/product/${p.id}"><h3>${escape(loc(p.name))}</h3></a>${p.reviews?`<div class="rating"><span class="star">★</span> ${p.rating} <span>(${p.reviews})</span></div>`:`<div class="rating">${t('สินค้าใหม่','New arrival')}</div>`}<div class="price-row"><strong class="price">${money(p.price)}</strong>${p.original>p.price?`<span class="old">${money(p.original)}</span>`:''}<button class="mini-add" data-action="add" data-id="${p.id}" aria-label="${t('เพิ่มลงตะกร้า','Add to cart')}">${icon('plus')}</button></div></div></article>`}
function storecard(s){return `<article class="store-card"><a href="#/store/${s.id}" class="store-cover" style="display:block"><img src="${escape(s.cover)}" alt="${escape(s.name)}" loading="lazy"></a><div class="store-body"><a href="#/store/${s.id}" class="avatar" style="color:${escape(s.color)}">${escape(s.name.slice(0,1))}</a><div><a href="#/store/${s.id}"><h3>${escape(s.name)} ${s.verified?'✓':''}</h3></a><p>${state.products.filter(p=>p.shop===s.id).length} ${t('สินค้า','products')} · ${t('ร้านค้าอิสระ','Independent shop')}</p></div><a class="follow" href="#/store/${s.id}">${t('เยี่ยมชม','Visit shop')} ↗</a></div></article>`}
function sectionTitle(title,subtitle,href,label=t('ดูทั้งหมด','View all')){return `<div class="section-title"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${href?`<a class="text-link" href="${href}">${label}${icon('arrow')}</a>`:''}</div>`}
function cats(){return `<div class="categories">${state.settings.categories.map(c=>`<button class="category ${category===c.id?'active':''}" data-action="category" data-id="${escape(c.id)}"><span class="cat-icon">${icon(c.icon)}</span>${escape(loc(c))}<small>${state.products.filter(p=>p.category===c.id).length} ${t('สินค้า','products')}</small></button>`).join('')}</div>`}
function filtered(items=state.products){return items.filter(p=>(!category||p.category===category)&&(!shopCategory||p.shopCategory===shopCategory)&&(filter!=='wishlist'||favorites.includes(p.id))&&(filter!=='deals'||p.original>p.price)&&(!query||[loc(p.name),shopName(p.shop),loc(p.description)].join(' ').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>sort==='low'?a.price-b.price:sort==='high'?b.price-a.price:sort==='discount'?(1-b.price/b.original)-(1-a.price/a.original):sort==='new'?b.id.localeCompare(a.id):hash(a.id+shuffle)-hash(b.id+shuffle))}
function hash(s){let h=0;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))|0;return h}
function controls(){return `<div class="toolbar"><button class="chip ${filter==='all'?'active':''}" data-action="filter" data-id="all">${t('แนะนำสำหรับคุณ','For you')}</button><button class="chip ${filter==='deals'?'active':''}" data-action="filter" data-id="deals">${t('ดีลราคาดี','Good finds')}</button><button class="chip" data-action="shuffle">${t('สุ่มสินค้าใหม่','Shuffle finds')} ↻</button>${category?`<button class="chip" data-action="category" data-id="">${t('ล้างหมวดหมู่','Clear category')} ×</button>`:''}<select id="sort" aria-label="${t('เรียงสินค้า','Sort products')}">${[['recommended',t('เรียงตาม: แนะนำ','Sort: Recommended')],['low',t('ราคา: ต่ำไปสูง','Price: Low to high')],['high',t('ราคา: สูงไปต่ำ','Price: High to low')],['discount',t('ส่วนลดมากที่สุด','Biggest discount')],['new',t('สินค้าใหม่','Newest')]].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></div>`}
function home(){const s=state.settings,featured=campaigns.filter(c=>c.status==='active').map(c=>state.shops.find(s=>s.id===c.shop)).filter(Boolean);return `${searchbox(true)}${s.showHero?`<section class="hero"><div class="hero-copy"><div class="eyebrow">GOOD FINDS. GOOD EVERYDAY.</div><h1>${escape(loc(s.heroTitle)).replaceAll('\n','<br>')}</h1><p>${escape(loc(s.heroText)).replaceAll('\n','<br>')}</p><a class="btn" href="#/catalog">${t('ค้นพบสิ่งที่ใช่','Find your everyday')}${icon('arrow')}</a><div class="hero-dots"><i></i><i></i><i></i></div></div><div class="hero-media"><img src="${escape(s.heroImage)}" alt="${t('มุมบ้านอบอุ่นและเรียบง่าย','A thoughtfully styled, warm living space')}" fetchpriority="high"><a class="hero-note" href="#/stores">${icon('leaf')}<div><strong>${t('มีเรื่องราวในทุกชิ้น','A story in every object')}</strong><small>${t('จากร้านเล็ก ๆ ที่ตั้งใจทำสิ่งดี ๆ','From independent shops, with care')}</small></div>${icon('arrow')}</a></div></section>`:''}<div class="benefits">${[['store',t('ร้านค้าที่ใส่ใจ','Independent shops'),t('คัดสรรสิ่งดี ๆ จากผู้ขาย','Thoughtfully chosen finds')],['shield',t('ชำระเงินอย่างมั่นใจ','Shop with confidence'),t('ตรวจสอบการโอนก่อนจัดส่ง','Payments reviewed before shipping')],['truck',t('ติดตามได้ทุกขั้นตอน','Follow every delivery'),t('แยกคำสั่งซื้อชัดเจนทุกร้าน','Clear tracking for each shop')],['heart',t('สิ่งที่ใช่สำหรับคุณ','A little more you'),t('เลือกสิ่งดี ๆ ให้ทุกวัน','Good things for the everyday')]].map(([i,a,b])=>`<div class="benefit">${icon(i)}<div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}</div><section class="section">${sectionTitle(t('ค้นหาตามความชอบ','Find your kind of good'),t('เลือกหมวดหมู่ แล้วค้นพบสิ่งที่เป็นคุณ','Explore the things that feel like you'),'#/catalog',t('ทุกหมวดหมู่','All categories'))}${cats()}</section><section class="section" id="picks">${sectionTitle(t('คัดมาให้ ในแบบของคุณ','Good finds, just for you'),t('พบกับสินค้าใหม่จากทุกร้านค้า สลับมาให้ค้นพบอยู่เสมอ','A fresh mix from independent shops. There’s always something to discover.'),'#/catalog')}${controls()}<div class="products">${filtered().slice(0,8).map(card).join('')}</div>${!filtered().length?empty(t('ยังไม่พบสินค้า','No products found'),t('ลองเปลี่ยนคำค้นหาหรือหมวดหมู่','Try another search or category')):''}</section>${featured.length?`<section class="section">${sectionTitle(t('ร้านค้าแนะนำ','In the spotlight')+`<span class="sponsor-label">${t('พื้นที่โฆษณา','Sponsored')}</span>`,t('ทำความรู้จักร้านค้าที่อยากให้คุณได้ค้นพบ','Meet the shops ready to become your new favorites'))}<div class="stores">${featured.slice(0,3).map(storecard).join('')}</div></section>`:''}${s.showStores?`<section class="section">${sectionTitle(t('ร้านเล็ก ๆ ความตั้งใจใหญ่ ๆ','Small shops. Big heart.'),t('เบื้องหลังสินค้าดี ๆ คือคนที่รักในสิ่งที่ทำ','Behind every good find is someone who cares.'),'#/stores',t('รู้จักทุกร้านค้า','Meet all shops'))}<div class="stores">${state.shops.slice(0,3).map(storecard).join('')}</div></section>`:''}<section class="banner"><div>${icon('store')}</div><div><h2>${t('ให้เรื่องราวของร้านคุณ เริ่มต้นที่นี่','Your shop. Your story. Start here.')}</h2><p>${t('สร้างร้านในแบบของคุณ และส่งต่อสินค้าดี ๆ ให้คนที่มองหา','Create a space for your brand and connect with people who get it.')}</p></div><a class="btn secondary" href="#/seller">${t('เปิดร้านกับเรา','Open your shop')}${icon('arrow')}</a></section>`}
function heading(title,sub=''){return `<div class="page-head"><div class="crumb"><a href="#/">${t('หน้าแรก','Home')}</a> / ${title}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`}
function catalog(){const items=filtered();return `${heading(t('สิ่งดี ๆ ทั้งหมด','All the good things'),query?t('ผลการค้นหา: ','Search results for: ')+escape(query):t('สินค้าจากร้านค้าที่ใส่ใจ เลือกสิ่งที่ใช่สำหรับคุณ','Thoughtful finds from independent shops. Find your everyday.'))}${cats()}${controls()}<p class="note">${items.length} ${t('สินค้า','products')}</p><div class="products">${items.map(card).join('')}</div>${!items.length?empty(t('ไม่พบสินค้าที่ค้นหา','No matching products'),t('ลองล้างตัวกรองหรือเปลี่ยนคำค้นหา','Try clearing filters or using a different search')):''}`}
function detail(id){const p=state.products.find(p=>p.id===id);if(!p)return empty(t('ไม่พบสินค้า','Product not found'),'');return `${heading(escape(loc(p.name)))}<div class="detail-grid"><div><div class="gallery-main" id="gallery-main"><img src="${escape(p.images[0])}" alt="${escape(loc(p.name))}"></div><div class="thumbs">${[...p.images.map(x=>({url:x,type:'image'})),...(p.videos||[]).map(x=>({url:x,type:'video'}))].map((m,i)=>`<button class="thumb ${i===0?'active':''}" data-action="media" data-url="${escape(m.url)}" data-type="${m.type}" aria-label="${m.type==='video'?t('เล่นวิดีโอ','Play video'):t('รูปที่ ','Image ')+(i+1)}">${m.type==='image'?`<img src="${escape(m.url)}" alt="">`:icon('play')}</button>`).join('')}</div><p class="note">${t('เลื่อนเพื่อดูภาพและวิดีโอทั้งหมด','Swipe to explore all images and videos')}</p></div><div class="detail-info"><a href="#/store/${p.shop}" class="shop-line">${icon('store')}${escape(shopName(p.shop))} ↗</a><h1>${escape(loc(p.name))}</h1><div class="rating"><span class="star">★</span> ${p.rating||'—'} (${p.reviews||0} ${t('รีวิว','reviews')})</div><div class="price-row"><strong class="price">${money(p.price)}</strong>${p.original>p.price?`<span class="old">${money(p.original)}</span><span class="badge">−${Math.round((1-p.price/p.original)*100)}%</span>`:''}</div><div class="detail-description">${escape(loc(p.description))}</div><p class="note">${t('คงเหลือ','Available')}: ${p.stock} ${t('ชิ้น','items')}</p><div class="quantity"><button data-action="detail-qty" data-id="-1" aria-label="${t('ลดจำนวน','Decrease quantity')}">−</button><span id="detail-qty">1</span><button data-action="detail-qty" data-id="1" aria-label="${t('เพิ่มจำนวน','Increase quantity')}">+</button></div><div class="detail-actions">${btn(t('เพิ่มลงตะกร้า','Add to bag')+' '+icon('bag'),'add-detail',p.id)}${btn(icon('heart'),'wish',p.id,'secondary')}</div><div class="detail-facts"><div class="row">${icon('truck')}${t('จัดส่งจาก','Shipped by')} ${escape(shopName(p.shop))}</div><div class="row">${icon('shield')}${t('โอนเงินผ่านบัญชี / พร้อมเพย์ และแจ้งสลิป','Bank transfer / PromptPay with slip confirmation')}</div></div></div></div><section class="section">${sectionTitle(t('จากร้านเดียวกัน','More from this shop'),'')}<div class="products">${state.products.filter(x=>x.shop===p.shop&&x.id!==p.id).slice(0,4).map(card).join('')}</div></section>`}
function cartGroups(){const groups=[];for(const x of cart){const p=state.products.find(p=>p.id===x.id);if(!p)continue;let g=groups.find(g=>g.shop===p.shop);if(!g){g={shop:p.shop,items:[],subtotal:0,shipping:0};groups.push(g)}g.items.push({...p,qty:x.qty});g.subtotal+=p.price*x.qty}for(const g of groups){const s=state.shops.find(s=>s.id===g.shop),threshold=s.freeShipping??state.settings.freeShipping;g.shipping=threshold>0&&g.subtotal>=threshold?0:s.shipping??state.settings.shipping}return groups}
function summary(groups,action=true){const total=groups.reduce((a,g)=>a+g.subtotal+g.shipping,0);return `<aside class="panel summary"><h2>${t('สรุปคำสั่งซื้อ','Order summary')}</h2><div class="summary-line"><span>${t('ราคาสินค้า','Subtotal')}</span><span>${money(groups.reduce((a,g)=>a+g.subtotal,0))}</span></div>${groups.map(g=>`<div class="summary-line"><span>${t('ค่าจัดส่ง','Shipping')} · ${escape(g.name||shopName(g.shop))}</span><span>${g.shipping?money(g.shipping):t('ฟรี','Free')}</span></div>`).join('')}<div class="summary-line total"><span>${t('ยอดรวม','Total')}</span><span>${money(total)}</span></div>${action?`<a class="btn" href="#/checkout">${t('ดำเนินการชำระเงิน','Continue to checkout')}${icon('arrow')}</a>`:''}<p class="note">${t('คำนวณค่าจัดส่งแยกตามร้านค้า ยอดรวมรวมค่าจัดส่งแล้ว','Shipping is calculated per shop and included in the total.')}</p></aside>`}
function cartPage(){const groups=cartGroups();return `${heading(t('ตะกร้าของคุณ','Your shopping bag'),`${cartCount()} ${t('ชิ้น จากร้านค้าที่คุณเลือก','thoughtful finds, ready for you')}`)}${!groups.length?empty(t('พื้นที่สำหรับสิ่งที่คุณชอบ','Make room for something good'),t('เริ่มค้นพบสินค้า แล้วเพิ่มสิ่งที่ใช่ลงตะกร้า','Explore our shops and add your favorite finds.')):`<div class="two-col"><div>${groups.map(g=>`<section class="panel"><h2 class="row">${icon('store')}<a href="#/store/${g.shop}">${escape(shopName(g.shop))}</a></h2>${g.items.map(p=>`<div class="cart-item"><a href="#/product/${p.id}"><img src="${escape(p.images[0])}" alt="${escape(loc(p.name))}"></a><div class="info"><a href="#/product/${p.id}"><h3>${escape(loc(p.name))}</h3></a><span class="note">${money(p.price)}</span><div style="margin-top:8px" class="quantity"><button data-action="qty" data-id="${p.id}" data-delta="-1" aria-label="${t('ลดจำนวน','Decrease quantity')}">−</button><span>${p.qty}</span><button data-action="qty" data-id="${p.id}" data-delta="1" aria-label="${t('เพิ่มจำนวน','Increase quantity')}">+</button></div></div><strong class="price">${money(p.price*p.qty)}</strong><button data-action="remove" data-id="${p.id}" aria-label="${t('นำออกจากตะกร้า','Remove from cart')}">×</button></div>`).join('')}<div class="summary-line"><span>${t('ค่าจัดส่งร้านนี้','Shop shipping')}</span><span>${money(g.shipping)}</span></div></section>`).join('')}</div>${summary(groups)}</div>`}`}
function signin(){return empty(t('เข้าสู่ระบบเพื่อดำเนินการต่อ','Sign in to continue'),t('ใช้บัญชี ChatGPT เพื่อจัดการสมาชิก ร้านค้า และคำสั่งซื้ออย่างปลอดภัย','Use your ChatGPT account to securely manage orders and your shop.'),'/signin-with-chatgpt?return_to='+encodeURIComponent('/'+location.hash),t('เข้าสู่ระบบด้วย ChatGPT','Continue with ChatGPT'))}
function checkout(){if(!state.user)return signin();const groups=cartGroups();if(!groups.length)return cartPage();const ready=state.settings.bankAccount&&state.settings.bankHolder&&state.settings.promptpay;return `${heading(t('ชำระเงิน','Checkout'),t('อีกเพียงไม่กี่ขั้นตอน สิ่งดี ๆ ก็พร้อมส่งถึงคุณ','A few small steps, and your good finds are on their way.'))}<div class="two-col"><div><form id="checkout-form" class="panel"><h2>1. ${t('ที่อยู่จัดส่ง','Delivery details')}</h2><div class="form-grid"><label>${t('ชื่อผู้รับ','Full name')}<input name="name" required autocomplete="name" value="${escape(state.user.name)}"></label><label>${t('เบอร์โทรศัพท์','Phone number')}<input name="phone" required type="tel" autocomplete="tel" pattern="[+0-9 \-]{9,16}"></label><label class="full">${t('ที่อยู่','Delivery address')}<textarea name="detail" required minlength="10" autocomplete="street-address"></textarea></label><label>${t('รหัสไปรษณีย์','Postal code')}<input name="postcode" required pattern="[0-9]{5}" inputmode="numeric" autocomplete="postal-code"></label></div><h2 style="margin-top:25px">2. ${t('วิธีชำระเงิน','Payment method')}</h2><div class="panel" style="background:#f4f6f0;padding:17px">${icon('shield')} ${t('โอนเงินผ่านบัญชีธนาคาร / PromptPay','Bank transfer / PromptPay')}<p class="note">${t('ระบบสร้าง QR พร้อมยอดรวมหลังยืนยันคำสั่งซื้อ จากนั้นอัปโหลดสลิปเพื่อให้ผู้ดูแลตรวจสอบ','Confirm your order to generate a QR with the exact total, then upload your payment slip for review.')}</p></div>${!ready?`<div class="notice">${t('ยังไม่เปิดรับชำระเงิน ผู้ดูแลต้องตั้งค่าบัญชีธนาคารและพร้อมเพย์ก่อน','Payments are not enabled yet. The administrator must configure the bank account and PromptPay recipient.')}</div>`:''}<button class="btn" ${!ready?'disabled style="opacity:.45;cursor:not-allowed"':''}>${t('ยืนยันคำสั่งซื้อและรับ QR','Place order & generate QR')}${icon('arrow')}</button></form></div>${summary(groups,false)}</div>`}
function promptpayPayload(id,amount){let target=id.length===10?'0066'+id.slice(1):id;const tlv=(tag,value)=>tag+String(value.length).padStart(2,'0')+value;let value='000201010212'+tlv('29',tlv('00','A000000677010111')+tlv(id.length===10?'01':'02',target))+'5802TH5303764'+tlv('54',Number(amount).toFixed(2))+'6304';let crc=0xffff;for(const ch of value){crc^=ch.charCodeAt(0)<<8;for(let i=0;i<8;i++)crc=(crc&0x8000)?(crc<<1)^0x1021:crc<<1;crc&=0xffff}return value+crc.toString(16).toUpperCase().padStart(4,'0')}
function payment(id){const o=orders.find(o=>o.id===id);if(!o)return empty(t('ไม่พบคำสั่งซื้อ','Order not found'),'','#/orders');let qr='';if(o.payment.promptpay){const q=qrcode(0,'M');q.addData(promptpayPayload(o.payment.promptpay,o.total));q.make();qr=q.createSvgTag({cellSize:4,margin:4,scalable:true})}return `${heading(t('ชำระเงินสำหรับคำสั่งซื้อ','Payment for order')+' '+escape(o.id))}<div class="two-col"><div class="panel"><h2>${t('สแกน QR เพื่อชำระเงิน','Scan to pay')}</h2><div class="qr-area"><strong>THAI QR PAYMENT · PromptPay</strong>${qr}<h3>${money(o.total)}</h3><span class="note">${t('รวมค่าจัดส่งแล้ว ตรวจสอบชื่อผู้รับก่อนโอนทุกครั้ง','Includes shipping. Verify the recipient name in your banking app.')}</span></div><div class="summary-line"><span>${t('ธนาคาร','Bank')}</span><strong>${escape(o.payment.bankName)}</strong></div><div class="summary-line"><span>${t('เลขที่บัญชี','Account number')}</span><strong>${escape(o.payment.bankAccount)}</strong></div><div class="summary-line"><span>${t('ชื่อบัญชี','Account holder')}</span><strong>${escape(o.payment.bankHolder)}</strong></div><div class="summary-line"><span>PromptPay</span><strong>${escape(o.payment.promptpay)}</strong></div>${['unpaid','rejected'].includes(o.paymentStatus)?`<form id="slip-form" data-id="${o.id}"><h2 style="margin-top:25px">${t('แจ้งยืนยันการโอน','Submit payment confirmation')}</h2>${o.paymentStatus==='rejected'?`<div class="notice">${t('สลิปเดิมไม่ผ่านการตรวจสอบ กรุณาตรวจสอบยอดและส่งใหม่','Your previous slip was rejected. Check the payment and resubmit.')}</div>`:''}<label class="upload">${t('แนบสลิปการโอน (JPG / PNG / WebP ไม่เกิน 25 MB)','Upload payment slip (JPG / PNG / WebP, max 25 MB)')}<input name="slip" type="file" accept="image/jpeg,image/png,image/webp" required></label><button class="btn">${t('ส่งสลิปให้ตรวจสอบ','Submit slip for review')}</button></form>`:`<div class="notice">${statusLabel(o.paymentStatus)}</div><a class="btn" href="#/orders">${t('ดูสถานะคำสั่งซื้อ','Track your order')}</a>`}</div>${summary(o.groups,false)}</div>`}
function statusLabel(s){return ({unpaid:t('รอชำระเงิน','Awaiting payment'),review:t('กำลังตรวจสอบสลิป','Payment under review'),paid:t('ชำระเงินแล้ว','Payment confirmed'),rejected:t('กรุณาส่งสลิปใหม่','Payment rejected'),pending:t('รอชำระเงิน','Awaiting payment'),preparing:t('กำลังเตรียมสินค้า','Preparing your order'),shipping:t('จัดส่งแล้ว','Shipped'),delivered:t('ได้รับสินค้าแล้ว','Delivered'),active:t('กำลังแสดง','Active'),expired:t('สิ้นสุดแล้ว','Expired')})[s]||s}
function orderCard(o,manage=false){return `<section class="panel"><div class="order-head"><div><strong>${escape(o.id)}</strong><p class="note">${new Date(o.created).toLocaleString(lang==='th'?'th-TH':'en-GB')}</p></div><span class="status ${['unpaid','review'].includes(o.paymentStatus)?'pending':o.paymentStatus==='rejected'?'rejected':''}">${statusLabel(o.paymentStatus)}</span></div>${o.groups.map(g=>`<div style="padding:10px 0"><div class="row between"><a href="#/store/${g.shop}" class="row">${icon('store')}<strong>${escape(g.name)}</strong></a><span class="status ${g.status==='shipping'?'shipping':''}">${statusLabel(g.status)}</span></div>${g.items.map(p=>`<div class="cart-item"><img src="${escape(p.image)}" alt=""><div class="info"><h3>${escape(loc(p.name))}</h3><span class="note">${p.qty} × ${money(p.price)}</span></div><strong>${money(p.price*p.qty)}</strong></div>`).join('')}<div class="summary-line"><span>${t('สินค้า','Items')} ${money(g.subtotal)} + ${t('ค่าจัดส่ง','shipping')} ${money(g.shipping)}</span><strong>${money(g.subtotal+g.shipping)}</strong></div><div class="steps">${['pending','preparing','shipping','delivered'].map((step,i)=>`<div class="step ${i<=['pending','preparing','shipping','delivered'].indexOf(g.status)?'done':''}">${statusLabel(step)}</div>`).join('')}</div>${g.tracking?`<div class="notice">${escape(g.carrier)} · <strong>${escape(g.tracking)}</strong> ${btn(t('คัดลอก','Copy'),'copy',g.tracking,'secondary')}</div>`:''}${manage&&o.paymentStatus==='paid'&&g.status!=='delivered'?btn(t('ใส่ / แก้ไขเลขติดตาม','Add / edit tracking'),'tracking',o.id+'|'+g.shop,'secondary'):''}${!manage&&g.status==='shipping'?btn(t('ยืนยันว่าได้รับสินค้า','Confirm delivery'),'received',o.id+'|'+g.shop,'secondary'):''}</div>`).join('')}<div class="summary-line total"><strong>${t('รวมทั้งคำสั่งซื้อ','Order total')}</strong><strong>${money(o.total)}</strong></div>${o.address?`<p class="note">${t('จัดส่งถึง','Deliver to')}: ${escape(o.address.name)} · ${escape(o.address.phone)}<br>${escape(o.address.detail)} ${escape(o.address.postcode)}</p>`:''}${!manage&&['unpaid','rejected'].includes(o.paymentStatus)?`<a class="btn" href="#/payment/${o.id}">${t('ชำระเงิน / แนบสลิป','Pay / Upload slip')}</a>`:''}${manage&&state.user?.role==='admin'&&o.paymentStatus==='review'?`<div class="inline-actions"><a class="btn secondary" href="${escape(o.slip)}" target="_blank" rel="noopener">${t('ดูสลิป','View payment slip')}</a>${btn(t('ยืนยันการโอน','Approve payment'),'approve',o.id)}${btn(t('ไม่ผ่าน','Reject'),'reject',o.id,'danger')}</div>`:''}</section>`}
function orderPage(){if(!state.user)return signin();const own=orders.filter(o=>o.user===state.user.id);return `${heading(t('คำสั่งซื้อของคุณ','Your orders'),t('สินค้า ค่าจัดส่ง และเลขติดตาม แยกชัดเจนในแต่ละร้าน','Items, shipping fees, and delivery updates — clearly separated by shop.'))}${own.length?own.map(o=>orderCard(o)).join(''):empty(t('ยังไม่มีคำสั่งซื้อ','Your next good find awaits'),t('คำสั่งซื้อของคุณจะแสดงที่นี่หลังชำระเงิน','Your orders will appear here after checkout.'))}`}
function storePage(id){const s=state.shops.find(x=>x.id===id);if(!s)return empty(t('ไม่พบร้านค้า','Shop not found'),'');const items=filtered(state.products.filter(p=>p.shop===id));return `<div class="shop-page" style="--ink:${escape(s.color)}"><div class="store-hero"><img src="${escape(s.cover)}" alt="${escape(s.name)}"><div class="store-intro"><div class="eyebrow">INDEPENDENT SHOP</div><h1>${escape(s.name)}</h1><p>${escape(loc(s.description))}</p></div></div><div class="toolbar"><button class="chip ${!shopCategory?'active':''}" data-action="shop-category" data-id="">${t('สินค้าทั้งหมด','All products')}</button>${s.categories.map(c=>`<button class="chip ${shopCategory===c?'active':''}" data-action="shop-category" data-id="${escape(c)}">${escape(c)}</button>`).join('')}</div><p class="note">${t('ค่าจัดส่ง','Shipping')} ${money(s.shipping)} · ${t('ส่งฟรีเมื่อครบ','Free shipping over')} ${money(s.freeShipping)}</p><div class="products">${items.map(card).join('')}</div>${!items.length?empty(t('ยังไม่มีสินค้าในหมวดนี้','No products in this collection'),t('ลองเลือกหมวดอื่น','Try another collection')):''}</div>`}
function account(){if(!state.user)return signin();return `${heading(t('บัญชีของฉัน','My account'))}<div class="two-col"><form class="panel" id="profile-form"><h2>${t('ข้อมูลสมาชิก','Member details')}</h2><label>${t('ชื่อที่แสดง','Display name')}<input name="name" required value="${escape(state.user.name)}" maxlength="80"></label><label>${t('อีเมล','Email')}<input value="${escape(state.user.email)}" disabled></label><p class="note">${t('เข้าสู่ระบบอย่างปลอดภัยผ่าน ChatGPT','Securely signed in with ChatGPT')}</p><button class="btn">${t('บันทึกข้อมูล','Save changes')}</button></form><div class="panel stack"><a href="#/orders">${t('คำสั่งซื้อของฉัน','My orders')} →</a><a href="#/seller">${t('จัดการร้านค้า','Seller studio')} →</a>${state.user.role==='admin'?`<a href="#/admin">${t('จัดการเว็บไซต์','Site administration')} →</a>`:''}<a href="/signout-with-chatgpt?return_to=/" target="_top">${t('ออกจากระบบ','Sign out')} →</a></div></div>`}
const field=(label,name,value,type='text',extra='')=>`<label>${label}<input type="${type}" name="${name}" value="${escape(value)}" ${extra}></label>`;
function shopForm(s={}){return `<form id="shop-form" class="panel" data-id="${escape(s.id||'')}"><h2>${s.id?t('ปรับแต่งร้านค้า','Customize your shop'):t('เริ่มต้นร้านค้าของคุณ','Create your shop')}</h2><div class="form-grid">${field(t('ชื่อร้านค้า','Shop name'),'name',s.name||'','text','required maxlength="80"')}${field(t('สีประจำร้าน','Brand color'),'color',s.color||'#203e34','color','class="color-input"')}<label>${t('คำอธิบายภาษาไทย','Description · Thai')}<textarea name="descriptionTh">${escape(s.description?.th||'')}</textarea></label><label>${t('คำอธิบายภาษาอังกฤษ','Description · English')}<textarea name="descriptionEn">${escape(s.description?.en||'')}</textarea></label>${field(t('ภาพหน้าปกร้าน (URL)','Shop cover image (URL)'),'cover',s.cover||'','text')}${field(t('หมวดหมู่ของร้าน คั่นด้วยจุลภาค','Shop categories, separated by commas'),'categories',s.categories?.join(', ')||'')}${field(t('ค่าขนส่งต่อคำสั่งซื้อ (บาท)','Shipping per order (THB)'),'shipping',s.shipping??state.settings.shipping,'number','min="0" step="0.01" required')}${field(t('ส่งฟรีเมื่อครบ (0 = ไม่ใช้)','Free shipping threshold (0 = disabled)'),'freeShipping',s.freeShipping??state.settings.freeShipping,'number','min="0" step="0.01" required')}<label class="full upload">${t('อัปโหลดภาพหน้าปกร้าน','Upload a shop cover')}<input type="file" name="coverFile" accept="image/jpeg,image/png,image/webp"></label></div><button class="btn">${t('บันทึกร้านค้า','Save shop')}</button></form>`}
function seller(){if(!state.user)return signin();const tab=route().split('/')[2]||'products',s=myShops.find(x=>x.id===selectedShop)||myShops[0];if(!s)return `${heading(t('สร้างร้านค้าในแบบของคุณ','Your shop starts here'),t('เชื่อมต่อกับคนที่ชอบสิ่งเดียวกับคุณ','Connect with people who appreciate what you make.'))}${shopForm()}`;selectedShop=s.id;const ps=state.products.filter(p=>p.shop===s.id),os=orders.filter(o=>o.groups.some(g=>g.shop===s.id));return `${heading(t('สตูดิโอร้านค้า','Seller studio'),escape(s.name))}${myShops.length>1?`<label>${t('เลือกร้านค้า','Select shop')}<select id="seller-shop">${myShops.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${escape(x.name)}</option>`).join('')}</select></label>`:''}<div class="tabs">${[['products',t('สินค้า','Products')],['orders',t('คำสั่งซื้อ','Orders')],['design',t('ปรับแต่งร้าน','Store design')],['sponsor',t('พื้นที่หน้าแรก','Homepage placement')]].map(([k,v])=>`<a class="tab ${tab===k?'active':''}" href="#/seller/${k}">${v}</a>`).join('')}<a class="tab" href="#/store/${s.id}">${t('ดูหน้าร้าน','View shop')} ↗</a></div>${tab==='design'?shopForm(s):tab==='orders'?os.length?os.map(o=>orderCard({...o,groups:o.groups.filter(g=>g.shop===s.id)},true)).join(''):empty(t('ยังไม่มีคำสั่งซื้อ','No orders yet'),t('คำสั่งซื้อของร้านจะแสดงที่นี่','Your shop’s orders will appear here.')):tab==='sponsor'?`<div class="panel"><div class="eyebrow">GROW YOUR GOOD</div><h2 style="margin-top:20px">${t('พาร้านของคุณไปอยู่หน้าแรก','Put your shop in the spotlight')}</h2><p class="note">${t('พื้นที่แนะนำร้านค้าแบบมีผู้สนับสนุน ผู้ดูแลตรวจสอบและเปิดแคมเปญหลังตกลงการชำระเงินกับร้านค้า','A sponsored homepage placement. Your administrator reviews the request and activates it after arranging payment with your shop.')}</p><h2>${money(state.settings.sponsorFee)} <span class="note">/ ${t('แคมเปญ','campaign')}</span></h2>${btn(t('ส่งคำขอซื้อพื้นที่','Request a placement'),'sponsor',s.id)}<div style="margin-top:20px">${campaigns.filter(c=>c.shop===s.id).map(c=>`<div class="summary-line"><span>${new Date(c.created).toLocaleDateString()} · ${money(c.fee)}</span><span class="status">${statusLabel(c.status)}</span></div>`).join('')}</div></div>`:`<div class="stat-grid"><div class="stat"><small>${t('สินค้าทั้งหมด','Products')}</small><strong>${ps.length}</strong></div><div class="stat"><small>${t('คำสั่งซื้อ','Orders')}</small><strong>${os.length}</strong></div><div class="stat"><small>${t('ยอดชำระแล้ว','Paid sales')}</small><strong>${money(os.filter(o=>o.paymentStatus==='paid').reduce((n,o)=>n+o.groups.filter(g=>g.shop===s.id).reduce((a,g)=>a+g.subtotal,0),0))}</strong></div></div><div class="panel"><div class="section-title"><h2>${t('สินค้าของร้าน','Shop products')}</h2>${btn(t('เพิ่มสินค้า','Add product')+' +','edit-product','')}</div><div class="table-wrap"><table><thead><tr><th>${t('สินค้า','Product')}</th><th>${t('ราคา','Price')}</th><th>${t('คงเหลือ','Stock')}</th><th>${t('จัดการ','Manage')}</th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="row"><img class="preview-image" src="${escape(p.images[0])}" alt=""><span>${escape(loc(p.name))}</span></div></td><td>${money(p.price)}</td><td>${p.stock}</td><td><div class="inline-actions"><button data-action="edit-product" data-id="${p.id}">${t('แก้ไข','Edit')}</button><button data-action="delete-product" data-id="${p.id}">${t('ลบ','Delete')}</button></div></td></tr>`).join('')}</tbody></table></div></div>`}`}
function productForm(id){const p=state.products.find(x=>x.id===id)||{},s=myShops.find(x=>x.id===selectedShop);modal(`<h2>${p.id?t('แก้ไขสินค้า','Edit product'):t('เพิ่มสินค้า','Add a product')}</h2><form id="product-form" data-id="${p.id||''}" class="form-grid">${field(t('ชื่อสินค้า · ไทย','Product name · Thai'),'nameTh',p.name?.th||'','text','required')}${field(t('ชื่อสินค้า · English','Product name · English'),'nameEn',p.name?.en||'','text','required')}<label>${t('หมวดหมู่เว็บไซต์','Website category')}<select name="category">${state.settings.categories.map(c=>`<option value="${c.id}" ${p.category===c.id?'selected':''}>${escape(loc(c))}</option>`).join('')}</select></label><label>${t('หมวดหมู่ร้านค้า','Shop category')}<select name="shopCategory"><option value="">—</option>${(s?.categories||[]).map(c=>`<option ${p.shopCategory===c?'selected':''}>${escape(c)}</option>`).join('')}</select></label>${field(t('ราคาตั้ง (บาท)','Original price (THB)'),'original',p.original||'','number','min="1" step="0.01" required')}${field(t('ราคาขาย (บาท)','Sale price (THB)'),'price',p.price||'','number','min="1" step="0.01" required')}${field(t('จำนวนคงเหลือ','Available quantity'),'stock',p.stock??1,'number','min="0" step="1" required')}<label class="full">${t('รายละเอียด · ไทย','Description · Thai')}<textarea name="descriptionTh">${escape(p.description?.th||'')}</textarea></label><label class="full">${t('รายละเอียด · English','Description · English')}<textarea name="descriptionEn">${escape(p.description?.en||'')}</textarea></label><label class="full">${t('URL รูปภาพ (หนึ่งรายการต่อบรรทัด)','Image URLs (one per line)')}<textarea name="images">${escape(p.images?.join('\n')||'')}</textarea></label><label class="full upload">${t('เพิ่มรูปภาพและวิดีโอหลายไฟล์ (ไฟล์ละไม่เกิน 25 MB)','Add multiple images and videos (max 25 MB each)')}<input name="files" type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/webm"></label><label class="full">${t('URL วิดีโอ MP4 / WebM (หนึ่งรายการต่อบรรทัด)','MP4 / WebM video URLs (one per line)')}<textarea name="videos">${escape(p.videos?.join('\n')||'')}</textarea></label><p class="note full">${t('ไฟล์ใหม่จะต่อท้ายรายการเดิม สามารถลบ URL เดิมเพื่อนำสื่อออกได้','New uploads are appended. Remove an existing URL to remove that media item.')}</p><button class="btn full">${t('บันทึกสินค้า','Save product')}</button></form>`)}
function adminPage(){if(!state.user)return signin();if(state.user.role!=='admin')return empty(t('เฉพาะผู้ดูแลระบบ','Administrator access required'),'','#/');const s=state.settings;return `${heading(t('จัดการเว็บไซต์','Site administration'),t('ปรับแบรนด์ หน้าหลัก การชำระเงิน และดูแลทุกคำสั่งซื้อ','Manage your brand, homepage, payment settings, and marketplace orders.'))}<div class="tabs">${[['appearance',t('แบรนด์และหน้าหลัก','Brand & homepage')],['categories',t('หมวดหมู่','Categories')],['payment',t('การชำระเงินและค่าจัดส่ง','Payment & shipping')],['orders',t('ตรวจสลิปและจัดส่ง','Payments & orders')],['sponsors',t('พื้นที่โฆษณา','Placements')]].map(([k,v])=>`<button class="tab ${adminTab===k?'active':''}" data-action="admin-tab" data-id="${k}">${v}</button>`).join('')}</div>${adminTab==='orders'?orders.length?orders.map(o=>orderCard(o,true)).join(''):empty(t('ยังไม่มีคำสั่งซื้อ','No orders yet'),''):adminTab==='sponsors'?`<div class="panel"><h2>${t('คำขอพื้นที่หน้าแรก','Homepage placement requests')}</h2><p class="note">${t('เปิดแคมเปญเมื่อยืนยันการชำระเงินกับร้านค้าแล้วเท่านั้น','Activate a placement only after confirming payment with the shop.')}</p>${campaigns.length?campaigns.map(c=>`<div class="summary-line row"><div>${escape(c.name)} · ${money(c.fee)} <span class="status">${statusLabel(c.status)}</span></div><div class="inline-actions"><button data-action="campaign" data-id="${c.id}|active">${t('เปิดแคมเปญ','Activate')}</button><button data-action="campaign" data-id="${c.id}|expired">${t('สิ้นสุด','End')}</button><button data-action="campaign" data-id="${c.id}|rejected">${t('ปฏิเสธ','Reject')}</button></div></div>`).join(''):`<p class="note">${t('ยังไม่มีคำขอ','No requests yet')}</p>`}</div>`:`<form id="settings-form" class="panel"><div class="form-grid">${adminTab==='appearance'?`${field(t('ชื่อเว็บไซต์','Website name'),'name',s.name,'text','required')}${field(t('สีหลัก','Primary color'),'color',s.color,'color','class="color-input"')}${field(t('คำโปรย · ไทย','Tagline · Thai'),'taglineTh',s.tagline.th)}${field(t('คำโปรย · English','Tagline · English'),'taglineEn',s.tagline.en)}${field(t('Logo URL','Logo URL'),'logo',s.logo)}<label class="upload">${t('อัปโหลด Logo','Upload logo')}<input type="file" name="logoFile" accept="image/jpeg,image/png,image/webp"></label>${field('Favicon URL','favicon',s.favicon)}<label class="upload">${t('อัปโหลด Favicon','Upload favicon')}<input type="file" name="faviconFile" accept="image/jpeg,image/png,image/webp"></label><label>${t('หัวข้อหน้าหลัก · ไทย','Hero title · Thai')}<textarea name="heroTitleTh">${escape(s.heroTitle.th)}</textarea></label><label>${t('หัวข้อหน้าหลัก · English','Hero title · English')}<textarea name="heroTitleEn">${escape(s.heroTitle.en)}</textarea></label><label>${t('ข้อความหน้าหลัก · ไทย','Hero description · Thai')}<textarea name="heroTextTh">${escape(s.heroText.th)}</textarea></label><label>${t('ข้อความหน้าหลัก · English','Hero description · English')}<textarea name="heroTextEn">${escape(s.heroText.en)}</textarea></label>${field(t('URL รูปหน้าหลัก','Hero image URL'),'heroImage',s.heroImage)}<label class="upload">${t('อัปโหลดรูปหน้าหลัก','Upload hero image')}<input type="file" name="heroFile" accept="image/jpeg,image/png,image/webp"></label>${field(t('ขนาดราคาขาย (px)','Sale price size (px)'),'priceSize',s.priceSize,'number','min="16" max="48"')}${field(t('ขนาด % ส่วนลด (px)','Discount badge size (px)'),'discountSize',s.discountSize,'number','min="10" max="28"')}<label class="check"><input name="showHero" type="checkbox" ${s.showHero?'checked':''}>${t('แสดงแบนเนอร์หลัก','Show hero banner')}</label><label class="check"><input name="showStores" type="checkbox" ${s.showStores?'checked':''}>${t('แสดงส่วนร้านค้า','Show independent shops section')}</label>`:adminTab==='payment'?`<div class="notice full">${t('ใช้ข้อมูลบัญชีจริงของผู้รับเท่านั้น ตรวจสอบชื่อในแอปธนาคารก่อนเปิดรับชำระเงิน','Enter the actual recipient details. Verify the name in a banking app before accepting payments.')}</div>${field(t('ชื่อธนาคาร','Bank name'),'bankName',s.bankName,'text','required')}${field(t('เลขบัญชี','Bank account number'),'bankAccount',s.bankAccount,'text','required')}${field(t('ชื่อเจ้าของบัญชี','Account holder name'),'bankHolder',s.bankHolder,'text','required')}${field(t('พร้อมเพย์ (เบอร์โทร 10 หลัก / เลขประชาชน 13 หลัก)','PromptPay (10-digit phone / 13-digit national ID)'),'promptpay',s.promptpay,'text','pattern="([0-9]{10}|[0-9]{13})" required')}${field(t('ค่าขนส่งเริ่มต้น (บาท)','Default shipping (THB)'),'shipping',s.shipping,'number','min="0" step="0.01" required')}${field(t('ส่งฟรีเมื่อครบ (0 = ปิด)','Free shipping threshold (0 = disabled)'),'freeShipping',s.freeShipping,'number','min="0" step="0.01" required')}${field(t('ราคาพื้นที่หน้าแรกต่อแคมเปญ (บาท)','Homepage placement per campaign (THB)'),'sponsorFee',s.sponsorFee,'number','min="0" step="0.01" required')}<p class="note full">${t('ร้านค้ากำหนดค่าจัดส่งของตัวเองได้ ยอด QR รวมค่าขนส่งจากทุกร้านแล้ว','Shops can override shipping settings. QR totals include shipping from every shop.')}</p>`:`<label class="full">${t('หมวดหมู่เว็บไซต์ (รหัส | ภาษาไทย | English)','Website categories (ID | Thai | English)')}<textarea name="categoriesText" style="min-height:250px">${escape(s.categories.map(c=>`${c.id} | ${c.th} | ${c.en}`).join('\n'))}</textarea></label><p class="note full">${t('หนึ่งหมวดหมู่ต่อบรรทัด ใช้รหัสเดิมสำหรับหมวดที่มีสินค้าอยู่ ร้านค้าสามารถกำหนดหมวดของร้านแยกต่างหาก','One category per line. Keep IDs for existing product categories. Shops manage their own separate collections.')}</p>`}</div><button class="btn">${t('บันทึกการตั้งค่า','Save settings')}</button></form>`}`}
async function load(){state=await api('bootstrap');campaigns=await api('sponsors');if(state.user){[orders,myShops]=await Promise.all([api('orders'),api('my-shop')])}theme()}
function theme(){const s=state.settings;document.documentElement.lang=lang;document.documentElement.style.setProperty('--ink',s.color||'#203e34');document.documentElement.style.setProperty('--price',(s.priceSize||23)+'px');document.documentElement.style.setProperty('--discount',(s.discountSize||12)+'px');if(s.favicon)$('link[rel="icon"]').href=s.favicon;document.title=s.name+' — '+loc(s.tagline)}
function render(){theme();const r=route();let content;if(r==='/')content=home();else if(r.startsWith('/catalog'))content=catalog();else if(r.startsWith('/product/'))content=detail(r.split('/')[2]);else if(r==='/cart')content=cartPage();else if(r==='/checkout')content=checkout();else if(r.startsWith('/payment/'))content=payment(r.split('/')[2]);else if(r==='/orders')content=orderPage();else if(r==='/stores')content=heading(t('ร้านค้าที่มีเรื่องราว','Meet the independent shops'),t('ค้นพบคนทำของดี และร้านที่ใส่ใจในทุกชิ้น','Good people. Thoughtful products. A shop for your kind of everyday.'))+`<div class="stores">${state.shops.map(storecard).join('')}</div>`;else if(r.startsWith('/store/'))content=storePage(r.split('/')[2]);else if(r.startsWith('/seller'))content=seller();else if(r==='/admin')content=adminPage();else if(r==='/account')content=account();else if(r==='/wishlist'){const ps=state.products.filter(p=>favorites.includes(p.id));content=heading(t('เก็บสิ่งที่ชอบไว้','Your saved good finds'))+(ps.length?`<div class="products">${ps.map(card).join('')}</div>`:empty(t('ยังไม่มีรายการโปรด','A space for your favorites'),t('แตะหัวใจบนสินค้าที่คุณชอบเพื่อบันทึกไว้','Tap the heart on any product to save it for later.')))}else content=empty(t('ไม่พบหน้านี้','Page not found'),'');$('#app').innerHTML=header()+`<main class="container">${content}</main>`+footer()}
async function upload(file,kind='media'){if(!file||!file.size)return '';if(file.size>25*1024*1024)throw Error(t('ไฟล์ต้องไม่เกิน 25 MB','Files must be smaller than 25 MB'));const r=await fetch('/api/upload?kind='+kind,{method:'POST',headers:{'Content-Type':file.type},body:file});const d=await r.json();if(!r.ok)throw Error(d.error);return d.url}
function add(id,qty=1){const p=state.products.find(x=>x.id===id);if(!p)return;const x=cart.find(x=>x.id===id);if((x?.qty||0)+qty>p.stock){toast(t('จำนวนเกินสินค้าคงเหลือ','Not enough stock available'));return}if(x)x.qty+=qty;else cart.push({id,qty});saveCart();render();toast(t('เพิ่มลงตะกร้าแล้ว','Added to your bag'))}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{
 if(a==='close')return closeModal();if(a==='lang'){lang=id;localStorage.setItem('baan-lang',lang);closeModal();return render()}if(a==='account'){location.hash='/account';return}if(a==='help'){modal(`<h2>${t('การชำระเงินและจัดส่ง','Payment & shipping')}</h2><p class="note">${t('ชำระเงินด้วยการโอนบัญชีธนาคารหรือสแกนพร้อมเพย์ตามยอดจริง รวมค่าขนส่งแยกตามร้าน จากนั้นส่งสลิปเพื่อให้ผู้ดูแลตรวจสอบ เมื่อยืนยันแล้วร้านค้าจะเตรียมสินค้าและระบุเลขติดตามในหน้าคำสั่งซื้อ','Pay by bank transfer or PromptPay using the exact total, including each shop’s shipping fee. Upload your slip for administrator review. Once payment is approved, each shop prepares your items and adds its tracking number to your orders.')}</p>`);return}
 if(a==='wish'){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];localStorage.setItem('baan-favorites',JSON.stringify(favorites));return render()}if(a==='add')return add(id);if(a==='add-detail')return add(id,Number($('#detail-qty').textContent));if(a==='detail-qty'){const p=state.products.find(p=>route().endsWith(p.id));$('#detail-qty').textContent=Math.min(p.stock,Math.max(1,Number($('#detail-qty').textContent)+Number(id)));return}if(a==='remove'){cart=cart.filter(x=>x.id!==id);saveCart();return render()}if(a==='qty'){const x=cart.find(x=>x.id===id),p=state.products.find(p=>p.id===id);x.qty=Math.min(p.stock,x.qty+Number(el.dataset.delta));cart=cart.filter(x=>x.qty>0);saveCart();return render()}
 if(a==='media'){$('#gallery-main').innerHTML=el.dataset.type==='video'?`<video src="${escape(el.dataset.url)}" controls playsinline autoplay></video>`:`<img src="${escape(el.dataset.url)}" alt="${t('รูปสินค้า','Product image')}">`;document.querySelectorAll('.thumb').forEach(x=>x.classList.remove('active'));el.classList.add('active');return}if(a==='category'){category=id;shopCategory='';if(route()!=='/'&&!route().startsWith('/catalog'))location.hash='/catalog';else render();return}if(a==='filter'){filter=id;return render()}if(a==='shuffle'){shuffle=Math.random();sort='recommended';return render()}if(a==='shop-category'){shopCategory=id;return render()}if(a==='admin-tab'){adminTab=id;return render()}if(a==='edit-product')return productForm(id);
 if(a==='delete-product'){modal(`<h2>${t('นำสินค้าออกจากร้าน?','Remove this product?')}</h2><p class="note">${t('สินค้าจะหายจากหน้าร้าน คำสั่งซื้อที่มีอยู่ยังเก็บข้อมูลเดิม','The product will be removed from your shop. Existing order records are retained.')}</p>${btn(t('ยืนยันการลบ','Confirm removal'),'confirm-delete',id,'danger')}`);return}if(a==='confirm-delete'){await api('products/'+id,'DELETE');closeModal();await load();render();return}
 if(a==='tracking'){const [oid,sid]=id.split('|'),g=orders.find(o=>o.id===oid).groups.find(g=>g.shop===sid);modal(`<h2>${t('ข้อมูลการจัดส่ง','Shipping details')}</h2><form id="tracking-form" data-id="${id}">${field(t('บริษัทขนส่ง','Shipping carrier'),'carrier',g.carrier,'text','required')}${field(t('เลขติดตามพัสดุ','Tracking number'),'tracking',g.tracking,'text','required')}<button class="btn">${t('บันทึกและแจ้งจัดส่ง','Save & mark as shipped')}</button></form>`);return}
 if(a==='copy'){await navigator.clipboard.writeText(id);toast(t('คัดลอกแล้ว','Copied'));return}if(a==='approve'||a==='reject'){await api('orders/'+id,'POST',{action:'payment',approved:a==='approve'});await load();render();toast(t('อัปเดตสถานะแล้ว','Payment status updated'));return}if(a==='received'){const [oid,shop]=id.split('|');await api('orders/'+oid,'POST',{action:'received',shop});await load();return render()}if(a==='sponsor'){el.disabled=true;await api('sponsors','POST',{shop:id});await load();render();toast(t('ส่งคำขอแล้ว ผู้ดูแลจะตรวจสอบและแจ้งวิธีชำระเงิน','Request sent. Your administrator will review and arrange payment.'));return}if(a==='campaign'){const [cid,status]=id.split('|');await api('sponsors/'+cid,'POST',{status});await load();render();return}
 }catch(err){toast(err.message);el.disabled=false}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;render()}if(e.target.id==='seller-shop'){selectedShop=e.target.value;render()}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();const d=new FormData(f),v=Object.fromEntries(d),submit=f.querySelector('button[type="submit"],button:not([type])');const original=submit?.innerHTML;if(submit){submit.disabled=true;submit.textContent=t('กำลังบันทึก...','Saving...')}try{
 if(f.id==='search'||f.id==='mobile-search'){query=v.q.trim();category='';shopCategory='';filter='all';if(route().startsWith('/catalog'))render();else location.hash='/catalog';return}
 if(f.id==='checkout-form'){const o=await api('orders','POST',{address:v,items:cart});cart=[];saveCart();orders.unshift(o);location.hash='/payment/'+o.id;return}
 if(f.id==='slip-form'){const slip=await upload(d.get('slip'),'slip');await api('orders/'+f.dataset.id,'POST',{action:'slip',slip});await load();render();toast(t('ส่งสลิปแล้ว รอผู้ดูแลตรวจสอบ','Slip submitted for review'));return}
 if(f.id==='profile-form'){await api('profile','POST',v)}
 if(f.id==='shop-form'){let cover=v.cover;if(d.get('coverFile')?.size)cover=await upload(d.get('coverFile'));await api('shops','POST',{id:f.dataset.id||undefined,name:v.name,color:v.color,cover,description:{th:v.descriptionTh,en:v.descriptionEn},categories:v.categories.split(',').map(s=>s.trim()).filter(Boolean),shipping:v.shipping,freeShipping:v.freeShipping})}
 if(f.id==='product-form'){const images=v.images.split('\n').map(x=>x.trim()).filter(Boolean),videos=v.videos.split('\n').map(x=>x.trim()).filter(Boolean);for(const file of d.getAll('files')){if(!file.size)continue;const url=await upload(file);(file.type.startsWith('video/')?videos:images).push(url)}await api('products','POST',{id:f.dataset.id||undefined,shop:selectedShop,name:{th:v.nameTh,en:v.nameEn},description:{th:v.descriptionTh,en:v.descriptionEn},category:v.category,shopCategory:v.shopCategory,price:v.price,original:v.original,stock:v.stock,images,videos});closeModal()}
 if(f.id==='settings-form'){const s={...state.settings};for(const k of ['name','color','logo','favicon','heroImage','priceSize','discountSize','bankName','bankAccount','bankHolder','promptpay','shipping','freeShipping','sponsorFee'])if(k in v)s[k]=v[k];for(const key of ['tagline','heroTitle','heroText'])if(key+'Th' in v)s[key]={th:v[key+'Th'],en:v[key+'En']};if(adminTab==='appearance'){s.showHero=d.has('showHero');s.showStores=d.has('showStores')}for(const [field,key] of [['logoFile','logo'],['faviconFile','favicon'],['heroFile','heroImage']])if(d.get(field)?.size)s[key]=await upload(d.get(field));if('categoriesText' in v){const lines=v.categoriesText.split('\n').filter(x=>x.trim());s.categories=lines.map(line=>{const [id,th,en]=line.split('|').map(s=>s.trim());if(!id||!th||!en)throw Error(t('รูปแบบหมวดหมู่ไม่ถูกต้อง','Invalid category format'));return {id,th,en,icon:state.settings.categories.find(c=>c.id===id)?.icon||'grid'}});if(new Set(s.categories.map(c=>c.id)).size!==s.categories.length)throw Error(t('รหัสหมวดหมู่ซ้ำกัน','Category IDs must be unique'))}await api('settings','POST',s)}
 if(f.id==='tracking-form'){const [id,shop]=f.dataset.id.split('|');await api('orders/'+id,'POST',{action:'tracking',shop,...v});closeModal()}
 await load();render();toast(t('บันทึกเรียบร้อยแล้ว','Changes saved'))
 }catch(err){toast(err.message)}finally{if(submit?.isConnected){submit.disabled=false;submit.innerHTML=original}}});
window.addEventListener('hashchange',async()=>{closeModal();if(route().includes('?deals'))filter='deals';if(!route().startsWith('/store/'))shopCategory='';if(['/orders','/admin'].includes(route())||route().startsWith('/seller')||route().startsWith('/payment')){try{await load()}catch(err){toast(err.message)}}render();window.scrollTo({top:0})});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const nodes=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
$('#app').innerHTML='<div class="loading">BAAN · '+t('กำลังจัดสิ่งดี ๆ ให้คุณ','Finding your everyday')+'…</div>';
try{await load();if(route().includes('?deals'))filter='deals';render()}catch(err){$('#app').innerHTML=`<div class="empty"><h2>${t('ยังเชื่อมต่อร้านค้าไม่ได้','We couldn’t reach the marketplace')}</h2><p>${escape(err.message)}</p><button class="btn" onclick="location.reload()">${t('ลองใหม่','Try again')}</button></div>`}
